--------------------------------------------------------
--  DDL for View VW_ALERTAS_CONDICIONES
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIERRA_EN_CALMA"."VW_ALERTAS_CONDICIONES" ("ID_PLANTA_USUARIO", "NOMBRE_COMUN", "TEMPERATURA", "HUMEDAD", "ALERTA") AS 
  SELECT 
    p.id_planta_usuario,
    bp.nombre_comun,
    ls.temperatura,
    ls.humedad,
    CASE 
        WHEN ls.temperatura < bp.req_temperatura_min THEN 'Temperatura baja'
        WHEN ls.temperatura > bp.req_temperatura_max THEN 'Temperatura alta'
        WHEN ls.humedad < bp.req_humedad THEN 'Humedad baja'
        ELSE 'Dentro de rango'
    END AS alerta
FROM lectura_sensores ls
JOIN sensores s ON ls.id_sensor = s.id_sensor
JOIN plantas_usuario p ON s.id_planta_usuario = p.id_planta_usuario
JOIN banco_plantas bp ON p.id_planta = bp.id_planta
;
--------------------------------------------------------
--  DDL for View VW_CUIDADOS_PROGRAMADOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIERRA_EN_CALMA"."VW_CUIDADOS_PROGRAMADOS" ("USUARIO", "PLANTA", "NOMBRE_COMUN", "TIPO_CUIDADO", "FECHA", "DETALLE", "PERIODO_FERTILIZACION", "PERIODO_PODA") AS 
  SELECT 
    u.nombre AS usuario,
    p.nombre_personalizado AS planta,
    bp.nombre_comun,
    hc.tipo_cuidado,
    hc.fecha,
    hc.detalle,
    bp.periodo_fertilizacion,
    bp.periodo_poda
FROM historial_cuidados hc
JOIN plantas_usuario p ON hc.id_planta_usuario = p.id_planta_usuario
JOIN banco_plantas bp ON p.id_planta = bp.id_planta
JOIN usuarios u ON p.id_usuario = u.id_usuario
;
--------------------------------------------------------
--  DDL for View VW_ESTADO_PLANTAS_USUARIO
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIERRA_EN_CALMA"."VW_ESTADO_PLANTAS_USUARIO" ("ID_USUARIO", "NOMBRE_USUARIO", "ID_PLANTA_USUARIO", "NOMBRE_COMUN", "NOMBRE_PERSONALIZADO", "TEMPERATURA", "HUMEDAD", "FECHA_HORA") AS 
  SELECT 
    u.id_usuario,
    u.nombre AS nombre_usuario,
    p.id_planta_usuario,
    bp.nombre_comun,
    p.nombre_personalizado,
    ls.temperatura,
    ls.humedad,
    ls.fecha_hora
FROM usuarios u
JOIN plantas_usuario p ON u.id_usuario = p.id_usuario
JOIN sensores s ON p.id_planta_usuario = s.id_planta_usuario
JOIN (
    SELECT id_sensor, MAX(fecha_hora) AS ultima_fecha
    FROM lectura_sensores
    GROUP BY id_sensor
) ult ON s.id_sensor = ult.id_sensor
JOIN lectura_sensores ls 
  ON ls.id_sensor = ult.id_sensor AND ls.fecha_hora = ult.ultima_fecha
JOIN banco_plantas bp ON p.id_planta = bp.id_planta
;
--------------------------------------------------------
--  DDL for View VW_HISTORIAL_RIEGOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIERRA_EN_CALMA"."VW_HISTORIAL_RIEGOS" ("USUARIO", "PLANTA", "NOMBRE_COMUN", "FECHA_HORA", "TIPO_RIEGO", "DURACION_SEG", "MOTIVO") AS 
  SELECT 
    u.nombre AS usuario,
    p.nombre_personalizado AS planta,
    bp.nombre_comun,
    r.fecha_hora,
    r.tipo_riego,
    r.duracion_seg,
    r.motivo
FROM riego r
JOIN lectura_sensores ls ON r.id_lectura = ls.id_lectura
JOIN sensores s ON ls.id_sensor = s.id_sensor
JOIN plantas_usuario p ON s.id_planta_usuario = p.id_planta_usuario
JOIN banco_plantas bp ON p.id_planta = bp.id_planta
JOIN usuarios u ON p.id_usuario = u.id_usuario
;
