--  DDL for Procedure POBLAR_LECTURAS_RIEGO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "TIERRA_EN_CALMA"."POBLAR_LECTURAS_RIEGO" IS
  CURSOR c_sensores IS
    SELECT ID_SENSOR FROM TIERRA_EN_CALMA.SENSORES
    WHERE ID_SENSOR IN (5, 6, 7, 8);

  v_id_lectura  NUMBER;
  v_temp        NUMBER(4,1);
  v_humedad     NUMBER(4,1);
  v_fecha       TIMESTAMP;
BEGIN
  FOR s IN c_sensores LOOP
    FOR dia IN 1..30 LOOP
      v_fecha := SYSTIMESTAMP - NUMTODSINTERVAL((30 - dia), 'DAY');
      v_temp := ROUND(DBMS_RANDOM.VALUE(24, 28), 1);
      v_humedad := ROUND(DBMS_RANDOM.VALUE(25, 60), 1);

        ID_SENSOR, TEMPERATURA, HUMEDAD, FECHA_HORA
      )
      VALUES (
        s.ID_SENSOR,
        v_temp,
        v_humedad,
        v_fecha + NUMTODSINTERVAL(DBMS_RANDOM.VALUE(0, 86400), 'SECOND')
      )
      RETURNING ID_LECTURA INTO v_id_lectura;

      IF v_humedad < 40 THEN
          ID_LECTURA, FECHA_HORA, TIPO_RIEGO, DURACION_SEG, MOTIVO
        )
        VALUES (
          v_id_lectura,
          v_fecha + NUMTODSINTERVAL(DBMS_RANDOM.VALUE(0, 86400), 'SECOND'),
          'automatico',   
          TRUNC(DBMS_RANDOM.VALUE(20, 60)),
          'Humedad baja detectada'
        );
      END IF;
    END LOOP;
  END LOOP;

  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Lecturas y riegos generados correctamente para sensores existentes (1,5,6,7,8).');
END;

/
--------------------------------------------------------
--  DDL for Procedure POBLAR_LECTURAS_RIEGO_500
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "TIERRA_EN_CALMA"."POBLAR_LECTURAS_RIEGO_500" AS
  v_temp NUMBER;
  v_hum  NUMBER;
  v_lectura NUMBER;
BEGIN
  -- Recorremos los 500 sensores DHT11
  FOR r IN (
    SELECT ID_SENSOR FROM TIERRA_EN_CALMA.SENSORES
    WHERE TIPO_SENSOR = 'DHT11' AND ROWNUM <= 500
  ) LOOP
    -- Generamos lecturas diarias durante 30 días (1 mes)
    FOR dia IN 1..30 LOOP
      v_temp := ROUND(DBMS_RANDOM.VALUE(18, 35), 1);  -- Temperatura entre 18 y 35 °C
      v_hum  := ROUND(DBMS_RANDOM.VALUE(30, 60), 1);  -- Humedad entre 30% y 60%

      -- Insertar lectura
        ID_SENSOR, TEMPERATURA, HUMEDAD, FECHA_HORA
      )
      VALUES (
        r.ID_SENSOR, v_temp, v_hum, SYSTIMESTAMP - dia
      )
      RETURNING ID_LECTURA INTO v_lectura;

      -- Activar riego automático si las condiciones lo requieren
      IF v_hum < 40 OR v_temp > 30 THEN
          ID_LECTURA, FECHA_HORA, TIPO_RIEGO, DURACION_SEG, MOTIVO
        ) VALUES (
          v_lectura,
          SYSTIMESTAMP - dia,
          'automatico',
          ROUND(DBMS_RANDOM.VALUE(30, 90)),
          'Activado por condiciones ambientales'
        );
      END IF;
    END LOOP;
  END LOOP;
  COMMIT;
END;

/
--------------------------------------------------------
--  DDL for Procedure POBLAR_PLANTAS_USUARIO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "TIERRA_EN_CALMA"."POBLAR_PLANTAS_USUARIO" IS
  v_id_planta NUMBER;
  v_nombre_planta VARCHAR2(100);
BEGIN
  FOR user_rec IN (SELECT ID_USUARIO FROM TIERRA_EN_CALMA.USUARIOS) LOOP
    -- Asignar dos plantas por usuario
    FOR i IN 1..2 LOOP
      v_id_planta := TRUNC(DBMS_RANDOM.VALUE(31, 36)); -- IDs del banco de plantas (25–30)

      SELECT NOMBRE_COMUN 
      INTO v_nombre_planta
      FROM TIERRA_EN_CALMA.BANCO_PLANTAS
      WHERE ID_PLANTA = v_id_planta;

         user_rec.ID_USUARIO,
         'activa',
         INITCAP(v_nombre_planta) || ' de ' || user_rec.ID_USUARIO);
    END LOOP;
  END LOOP;

  COMMIT;
  DBMS_OUTPUT.PUT_LINE(' Se asignaron 2 plantas a cada usuario correctamente.');
END;

/
--------------------------------------------------------
--  DDL for Procedure POBLAR_USUARIOS_REALES
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "TIERRA_EN_CALMA"."POBLAR_USUARIOS_REALES" IS
  v_nombres   SYS.DBMS_DEBUG_VC2COLL := SYS.DBMS_DEBUG_VC2COLL(
    'Camila', 'Valentina', 'Sofía', 'Isabella', 'Mariana',
    'Sara', 'Lucía', 'Laura', 'Paula', 'Gabriela',
    'Juan', 'Mateo', 'Santiago', 'Samuel', 'Nicolás',
    'Daniel', 'Felipe', 'Andrés', 'David', 'Tomás'
  );

  v_apellidos SYS.DBMS_DEBUG_VC2COLL := SYS.DBMS_DEBUG_VC2COLL(
    'Gómez', 'Rodríguez', 'Martínez', 'García', 'López',
    'Hernández', 'Pérez', 'Torres', 'Ramírez', 'Flores',
    'Díaz', 'Morales', 'Castro', 'Vargas', 'Suárez',
    'Jiménez', 'Rojas', 'Castaño', 'Mendoza', 'Salazar'
  );

  v_nombre    VARCHAR2(50);
  v_apellido  VARCHAR2(50);
  v_correo    VARCHAR2(100);
  v_telefono  VARCHAR2(15);
  v_id        NUMBER;
BEGIN
  FOR i IN 1..1500 LOOP
    -- Elegir nombres aleatorios
    v_nombre   := v_nombres(TRUNC(DBMS_RANDOM.VALUE(1, v_nombres.COUNT + 1)));
    v_apellido := v_apellidos(TRUNC(DBMS_RANDOM.VALUE(1, v_apellidos.COUNT + 1)));

    -- Generar correo y teléfono
    v_correo   := LOWER(v_nombre || '.' || v_apellido || i || '@gmail.com');
    v_telefono := '3' || TRUNC(DBMS_RANDOM.VALUE(100000000, 999999999));

    -- Obtener el siguiente ID
    v_id := TIERRA_EN_CALMA.SEQ_USUARIOS.NEXTVAL;

    -- Insertar solo si el ID no existe ya
    BEGIN
        ID_USUARIO,
        NOMBRE,
        APELLIDO,
        TELEFONO,
        CORREO_ELECTRONICO,
        CONTRASENA
      )
      SELECT v_id, v_nombre, v_apellido, v_telefono, v_correo, 'Tierra2025'
      FROM DUAL
      WHERE NOT EXISTS (
        SELECT 1 FROM TIERRA_EN_CALMA.USUARIOS WHERE ID_USUARIO = v_id
      );

    EXCEPTION
      WHEN DUP_VAL_ON_INDEX THEN
        NULL; -- ignora si ya existe un registro con el mismo ID o correo
    END;
  END LOOP;

  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Inserción completada, ignorando duplicados existentes.');
END;

/
