    );
  END LOOP;
  COMMIT;
END;

/
--------------------------------------------------------
--  DDL for Package PKG_CENTRAL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "TIERRA_EN_CALMA"."PKG_CENTRAL" AS

  -- Procedimiento para controlar el riego
  PROCEDURE CONTROL_RIEGO (
    p_id_planta_usuario IN NUMBER,
    p_temperatura       IN NUMBER,
    p_humedad           IN NUMBER
  );

  -- Función para obtener el último tipo de riego
  FUNCTION OBTENER_ULTIMO_TIPO_RIEGO (
    p_id_planta_usuario IN NUMBER
  ) RETURN VARCHAR2;

END PKG_CENTRAL;

/
--------------------------------------------------------
--  DDL for Package Body PKG_CENTRAL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "TIERRA_EN_CALMA"."PKG_CENTRAL" AS

  ------------------------------------------------------------------
  PROCEDURE CONTROL_RIEGO (
    p_id_planta_usuario IN NUMBER,
    p_temperatura       IN NUMBER,
    p_humedad           IN NUMBER
  ) IS
    v_id_sensor   NUMBER;
    v_id_lectura  NUMBER;
  BEGIN
    SELECT ID_SENSOR INTO v_id_sensor
    FROM TIERRA_EN_CALMA.SENSORES
    WHERE ID_PLANTA_USUARIO = p_id_planta_usuario;

      ID_SENSOR, TEMPERATURA, HUMEDAD, FECHA_HORA
    )
    VALUES (
      v_id_sensor,
      p_temperatura,
      p_humedad,
      SYSTIMESTAMP
    )
    RETURNING ID_LECTURA INTO v_id_lectura;

    IF p_humedad < 40 OR p_temperatura > 30 THEN
        ID_LECTURA, FECHA_HORA, TIPO_RIEGO, DURACION_SEG, MOTIVO
      )
      VALUES (
        v_id_lectura,
        SYSTIMESTAMP,
        'automatico',
        45,
        'Activado por condiciones ambientales'
      );
      DBMS_OUTPUT.PUT_LINE('Riego automático activado para la planta ' || p_id_planta_usuario);
    ELSE
      DBMS_OUTPUT.PUT_LINE('No se requiere riego para la planta ' || p_id_planta_usuario);
    END IF;

    COMMIT;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE('No existe sensor asociado a la planta ' || p_id_planta_usuario);
  END CONTROL_RIEGO;

  ------------------------------------------------------------------
  FUNCTION OBTENER_ULTIMO_TIPO_RIEGO (
    p_id_planta_usuario IN NUMBER
  ) RETURN VARCHAR2 IS
    v_tipo_riego VARCHAR2(20);
  BEGIN
    SELECT R.TIPO_RIEGO
    INTO v_tipo_riego
    FROM TIERRA_EN_CALMA.RIEGO R
    JOIN TIERRA_EN_CALMA.LECTURA_SENSORES L
      ON R.ID_LECTURA = L.ID_LECTURA
    JOIN TIERRA_EN_CALMA.SENSORES S
      ON L.ID_SENSOR = S.ID_SENSOR
    WHERE S.ID_PLANTA_USUARIO = p_id_planta_usuario
    ORDER BY R.FECHA_HORA DESC
    FETCH FIRST 1 ROWS ONLY;

    RETURN v_tipo_riego;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 'Sin riegos registrados';
  END OBTENER_ULTIMO_TIPO_RIEGO;

END PKG_CENTRAL;

